// 导入组件
import Vue from 'vue';
import Router from 'vue-router';
// 登录
import login from '@/views/login';
// 首页
import index from '@/views/index';
// 摄像机页面
import camera from '@/views/camera/index';
// 识别信息页面
import identify from '@/views/identify/index';
// 区页面
import area from '@/views/blocks/area/index';
// 块页面
import piece from '@/views/blocks/piece/index';
// 人员管理页面
import employee from '@/views/employee/index';
// 采摘信息管理
import pick from '@/views/dopick/pick/index';
import nopick from '@/views/dopick/nopick/index';

// 启用路由
Vue.use(Router);

// 导出路由 
const router =  new Router({
    mode: 'hash',
    routes: [{
        path: '/',
        name: '',
        component: login,
        hidden: true,
        meta: {
            requireAuth: false
        }
    }, {
        path: '/login',
        name: '登录',
        component: login,
        hidden: true,
        meta: {
            requireAuth: false
        }
    }, {
        path: '/index',
        name: '首页',
        component: index,
        iconCls: 'el-icon-tickets',
        children: [{
            path: '/camera/index',
            name: '摄像机管理',
            component: camera,
            meta: {
                requireAuth: true
            }
        }, {
            path: '/identify/index',
            name: '识别信息管理',
            component: identify,
            meta: {
                requireAuth: true
            }
        }, {
            path: '/blocks/area/index',
            name: '区管理',
            component: area,
            meta: {
                requireAuth: true
            }
        }, {
            path: '/blocks/piece/index',
            name: '块管理',
            component: piece,
            meta: {
                requireAuth: true
            }
        }, {
            path: '/employee/index',
            name: '用户管理',
            component: employee,
            meta: {
                requireAuth: true
            }
        }, {
            path: '/dopick/pick/index',
            name: '采摘完成信息',
            component: pick,
            meta: {
                requireAuth: true
            }
        }, {
            path: '/dopick/nopick/index',
            name: '预采摘信息',
            component: nopick,
            meta: {
                requireAuth: true
            }
        },
        ]
    }]
})

// 导航守卫
// 使用 router.beforeEach 注册一个全局前置守卫，判断用户是否登陆
router.beforeEach((to, from, next) => {
    //如果去往登录页则放行 
    if (to.path === '/') {
        next();
    } else {
        // 从本地存储里获取token
        let token = localStorage.getItem('logintoken');
        // 判断token是否为空如果为空则跳转到登录页 如果有则放行
        if (token === null || token === '') {
            next({ path: '/' });
        } else {
            next();
        }
    }
});

export default router


