<template>
  <div>
    <!-- 面包屑导航 -->
    <el-breadcrumb
      separator-class="el-icon-arrow-right"
      style="padding-bottom: 20px"
    >
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">人员信息管理</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height:80px">
      <el-form :inline="true" class="demo-form-inline">
        <el-form-item label="用户名称">
          <el-input placeholder="输入用户名称" v-model="selectName"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect">查询</el-button>
          <el-button type="primary" @click="reload">刷新页面</el-button>
        </el-form-item>
        <!-- 添加按钮 -->
        <el-button
          type="primary"
          icon="el-icon-plus"
          style="float: right"
          @click="showDialog"
          >添加人员</el-button
        >
      </el-form>
    </el-card>

    <!-- 表格数据 -->
    <el-table :data="list" border style="width: 100%" :row-class-name="tableRowClassName">
      <el-table-column prop="id" label="用户id"> </el-table-column>
      <el-table-column prop="name" label="用户名称"> </el-table-column>
      <el-table-column prop="username" label="账号"> </el-table-column>
      <el-table-column prop="phone" label="手机号"> </el-table-column>
      <el-table-column prop="sex" label="性别"> </el-table-column>
      <el-table-column prop="status" label="状态"> </el-table-column>
      <el-table-column prop="createTime" label="创建时间"> </el-table-column>
      <el-table-column prop="updateTime" label="操作时间"> </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="{ row }">
          <el-button size="mini" @click="updateEmployee(row)" :disabled="row.id==1 ? true : false">修改</el-button>
          <el-button size="mini" type="danger" @click="deleteEmployee(row)" :disabled="row.id==1 ? true : false"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
    -->
    <el-pagination
      style="margin-top: 20px; textalign: center"
      :current-page="page"
      :page-sizes="[5, 10, 15]"
      :page-size="pageSize"
      :total="total"
      @current-change="getPageList"
      @size-change="handleSizeChange"
      layout="prev, pager, next, jumper,->, sizes, total"
    >
    </el-pagination>

    <!-- dialog弹出框/添加人员信息 -->
    <el-dialog title="添加人员信息" :visible.sync="dialogFormVisible">
      <el-form style="width: 80%" :model="Form" :rules="rules" ref="ruleForm">
        <el-form-item label="用户名称" prop="name">
          <el-input autocomplete="off" v-model="Form.name"></el-input>
        </el-form-item>
        <el-form-item label="账号" prop="username">
          <el-input autocomplete="off" v-model="Form.username"></el-input>
        </el-form-item>
        <el-form-item label="手机号" prop="phone">
          <el-input autocomplete="off" v-model="Form.phone"></el-input>
        </el-form-item>
        <!-- <el-form-item label="超管" prop="isAdmin">
          <el-input autocomplete="off" v-model="Form.isAdmin"></el-input>
        </el-form-item> -->
        <el-form-item label="身份" prop="isAdmin">
          <el-select placeholder="请选择" v-model="Form.isAdmin">
            <el-option label="园区负责人" value="0"></el-option>
            <el-option label="采摘人员" value="2"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="性别" prop="sex">
          <el-select placeholder="请选择" v-model="Form.sex">
            <el-option label="男" value="1"></el-option>
            <el-option label="女" value="0"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="状态" prop="status">
          <el-select placeholder="请选择" v-model="Form.status">
            <el-option label="可用" value="1"></el-option>
            <el-option label="禁用" value="0"></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="AddEmployee">确 定</el-button>
      </div>
    </el-dialog>
    <!-- dialog弹出框/修改人员信息 -->
    <el-dialog title="修改人员信息" :visible.sync="dialogFormVisible2">
      <el-form style="width: 80%" :model="uForm" :rules="rules2" ref="ruleForm2">
        <el-form-item label="用户名称" prop="name">
          <el-input autocomplete="off" v-model="uForm.name"></el-input>
        </el-form-item>
        <el-form-item label="手机号" prop="phone">
          <el-input autocomplete="off" v-model="uForm.phone"></el-input>
        </el-form-item>
        <el-form-item label="身份" prop="isAdmin">
          <el-select placeholder="请选择" v-model="Form.isAdmin">
            <el-option label="园区负责人" value="0"></el-option>
            <el-option label="采摘人员" value="2"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="性别" prop="sex">
          <el-select placeholder="请选择" v-model="uForm.sex">
            <el-option label="男" value="1"></el-option>
            <el-option label="女" value="0"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="状态" prop="status">
          <el-select placeholder="请选择" v-model="uForm.status">
            <el-option label="可用" value="1"></el-option>
            <el-option label="禁用" value="0"></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible2 = false">取 消</el-button>
        <el-button type="primary" @click="UpdateEmployee">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import {
  EmployeeList,
  DeleteEmployee,
  EmployeeAdd,
  EmployeeUpdate,
  SelectByName,
} from "@/api/employeeMG";
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "employee",
  data() {
    // 自定义校验规则
    var validateName = (rule, value, callback) => {
      if (value.length < 2 || value.length > 10) {
        callback(new Error("请输入正确的名称:2-10位"));
      } else {
        callback();
      }
    };
    var validateUserName = (rule, value, callback) => {
      if (value.length < 3 || value.length > 16) {
        callback(new Error("请输入正确的账号:3-16位"));
      } else {
        callback();
      }
    };
    return {
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 10,
      total: 0,
      list: [],
      // 弹出框
      dialogFormVisible: false,
      dialogFormVisible2: false,
      Form: {
        name: "",
        username: "",
        phone: "",
        sex: "",
        status: "",
        isAdmin: "",
      },
      uForm: {
        name: "",
        password: "",
        phone: "",
        sex: "",
        status: "",
        isAdmin: "",
      },
      // 表单验证规则
      rules: {
        name: [
          { required: true, message: "请输入用户名称", trigger: "blur" },
          { validator: validateName, trigger: "change" },
        ],
        username: [
          { required: true, message: "请输入账号", trigger: "blur" },
          { validator: validateUserName, trigger: "change" },
        ],
        phone: [{ required: true, message: "请输入手机号", trigger: "blur" }],
        sex: [{ required: true, message: "请选择性别", trigger: "blur" }],
        status: [{ required: true, message: "请选择状态", trigger: "blur" }],
        isAdmin: [{ required: true, message: "请选择身份", trigger: "blur" }],
      },
      rules2: {
        name: [
          { required: true, message: "请输入用户名称", trigger: "blur" },
          { validator: validateName, trigger: "change" },
        ],
        phone: [{ required: true, message: "请输入手机号", trigger: "blur" }],
        sex: [{ required: true, message: "请选择性别", trigger: "blur" }],
        status: [{ required: true, message: "请选择状态", trigger: "blur" }],
        isAdmin: [{ required: true, message: "请选择身份", trigger: "blur" }],
      },
      // 查询条件
      selectName: "",
    };
  },
  mounted() {
    this.getPageList();
  },
  methods: {
    // 获取人员信息展示列表
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      EmployeeList(page, pageSize)
        .then((res) => {
          // console.log(res.data);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            this.list = res.data.records;
            //分页赋值
            this.total = res.data.total;
            for(var i = 0; i < this.list.length; i++) {
              if(this.list[i].sex == '1') {
                this.list[i].sex = "男"
              } else {
                this.list[i].sex = "女"
              }
              if(this.list[i].status === 1) {
                this.list[i].status = "可用"
              } else {
                this.list[i].status = "禁用"
              }
            }
            // console.log(this.list);
            
          }
        })
        /* .catch((err) => {
          this.$message.error("加载失败，请稍后重试");
        }) */;
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 点击添加按钮
    showDialog() {
      this.dialogFormVisible = true;
      // 清除数据
      this.Form = { name: "", username: "", phone: "", sex: "", status: "", isAdmin: "" };
    },
    // 点击修改按钮
    updateEmployee(row) {
      this.dialogFormVisible2 = true;
      //将已有信息给对话框
      this.uForm = { ...row };
    },
    // 添加人员信息
    AddEmployee() {
      // 当全部字段通过，再去进行请求
      this.$refs.ruleForm.validate((success) => {
        if (success) {
          this.dialogFormVisible = false;
          //发送请求
          EmployeeAdd(this.Form).then((res) => {
            // console.log(res);
            if (res.data.code == 1) {
              this.$message({
                type: "success",
                message: "添加人员信息成功",
              });
              this.getPageList();
            } else {
              this.$message({
                type: "warning",
                message: res.data.msg,
              });
            }
          });
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 修改人员信息
    UpdateEmployee() {
      // 当全部字段通过，再去进行请求
      this.$refs.ruleForm2.validate((success) => {
        if (success) {
          this.dialogFormVisible2 = false;
          // console.log('改后',this.uForm);
          //发送请求
          EmployeeUpdate(this.uForm).then((res) => {
            // console.log('update',res);
            if (res.data.code == 1) {
              this.$message({
                type: "success",
                message: "修改人员信息成功",
              });
              this.getPageList(this.page);
            } else {
              this.$message({
                type: "warning",
                message: res.data.msg,
              });
            }
          });
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 删除操作
    deleteEmployee(row) {
      // 弹框
      this.$confirm(`确定删除${row.name}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      }).then(() => {
        // console.log(row.id);
        DeleteEmployee(row.id)
          .then((res) => {
            // console.log(res);
            if (res.code == 1) {
              this.$message({
                type: "success",
                message: "人员信息已删除!",
              });
              //再次获取列表数据
              this.getPageList(
                this.list.length > 1 ? this.page : this.page - 1
              );
            } else {
              this.$message({
                type: "info",
                message: res.msg,
              });
            }
          })
          .catch((err) => {
            this.loading = false;
            this.$message.error("人员信息删除失败，请稍后再试！");
          });
      });
    },
    // 查询操作
    getSelect() {
      SelectByName(this.selectName, 1, 999)
        .then((res) => {
          // console.log(res);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
            this.list = res.data.records;
            this.total = res.data.total
            for(var i = 0; i < this.list.length; i++) {
              if(this.list[i].sex == '1') {
                this.list[i].sex = "男"
              } else {
                this.list[i].sex = "女"
              }
              if(this.list[i].status === 1) {
                this.list[i].status = "可用"
              } else {
                this.list[i].status = "禁用"
              }
            }
            // console.log(this.list);
          }
          // this.dialogGet = true;
        })
    },
    SelectOn() {
      this.reload();
    },
    // 禁用样式
    tableRowClassName({row, rowIndex}) {
        if (row.status == "禁用") {
          return 'warning-row';
        }
      }
  },
};
</script>

<style>
 .el-table .warning-row {
    background: #feeeed;
  }
</style>


