/**
* 头部菜单
* rgb(70,138,255)
*/ 
<template>
  <el-menu class="el-menu-demo" mode="horizontal" background-color="rgba(41,189,217,.1)" text-color="#000" active-text-color="#000">
    <el-button class="buttonimg">
      <img class="showimg" :src="collapsed?imgsq:imgshow" @click="toggle(collapsed)">
    </el-button>
    <el-submenu index="2" class="submenu">
      <!-- <template slot="title">{{user.userRealName}}</template> -->
      <template slot="title">{{user.name}}
        <img class="logoimg" :src=user.headImg alt="" />
        </template>
      
      <el-menu-item @click="exit()" index="2-3">退出</el-menu-item>
    </el-submenu>
  </el-menu>
</template>
<script>
import { logout } from '../api/userMG'
export default {
  name: 'navcon',
  data() {
    return {
      collapsed: true,
      imgshow: require('../assets/img/show.png'),
      imgsq: require('../assets/img/sq.png'),
      user: {}
    }
  },
  // 创建完毕状态(里面是操作)
  created() {
    this.user = JSON.parse(localStorage.getItem('userdata'))
    // console.log('user',this.user);
  },
  methods: {
    // 退出登录
    exit() {
      this.$confirm('退出登录, 是否继续?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      })
        .then(() => {
          setTimeout(() => {
            logout()
            .then(res => {
              console.log(res);
              if(res.data.code == 1){
                localStorage.removeItem('userInfo')
                localStorage.removeItem('logintoken')
                this.$store.commit('logout', 'false')
                this.$router.push({ path: '/login' })
                this.$message({
                  type: 'success',
                  message: '已退出登录!'
                })
              } else {
                this.$message({
                  type: 'error',
                  message: res.data.msg
                })
              }
              
            })
          }, 1000)
        })
        .catch(() => {
          this.$message({
            type: 'info',
            message: '已取消'
          })
        })
    },
    // 切换显示
    toggle(showtype) {
      this.collapsed = !showtype
      this.$root.Bus.$emit('toggle', this.collapsed)
    },

  }
}
</script>
<style scoped>
.el-menu-vertical-demo:not(.el-menu--collapse) {
  border: none;
}
.el-menu-demo {
  background: linear-gradient(-90deg, #29bdd9 0%, #276ace 100%);
}
.submenu {
  float: right;
}
.el-submenu__title:active {
  background-color: #00a6ac;
}
.buttonimg {
  height: 60px;
  background-color: transparent;
  border: none;
}
.showimg {
  width: 26px;
  height: 26px;
  position: absolute;
  top: 17px;
  left: 17px;
}
.showimg:active {
  border: none;
  background-color: #00a6ac;
}
.logoimg {
  width: 40px;
  height: 40px;
}
</style>


