import axios from 'axios';
import { loginreq, req } from './axiosFun';


export const PieceList = (page,pageSize) => { return req("get", "/fruitTree?page="+page+"&pageSize="+pageSize) };

// 添加和修改信息
export const AddOrUpdatePiece = (fruitTree) => {
    if(fruitTree.id){
        return axios.put("/fruitTree", fruitTree)
    } else { 
        return axios.post("/fruitTree", fruitTree) 
    }
}

// 添加果蔬类型
export const AddType = (type) => { return axios.post("/area/addType", type) }


// 删除信息
export const DeletePiece = (id) => { return axios.delete("/fruitTree/" + id ).then(res => res.data) };

// 获取筛选列表
export const GetType = () => { return req("get", "/fruitTree/showType").then(res => res.data) }

// 根据果蔬类型查找信息
export const SelectByType = (type,page,pageSize) => { return axios.get("/fruitTree?page="+page+"&pageSize="+pageSize+"&type="+type).then(res => res.data)}

// 根据区号展示果蔬编号
export const getTreeId = (id) => { return req("get", "/fruitTree/select/{areaId}?areaId=" + id).then(res => res.data) }


