<template>
  <div>
    <!-- 面包屑导航 -->
    <el-breadcrumb
      separator-class="el-icon-arrow-right"
      style="padding-bottom: 20px"
    >
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">识别信息管理</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height:80px">
      <el-form :inline="true" class="demo-form-inline" style="height: 50px">
        <el-form-item style="float: right">
          <el-button type="primary" @click="reload">刷新页面</el-button>
        </el-form-item>
      </el-form>
    </el-card>
    <el-card>
      <el-table :data="list" border style="width: 100%">
        <el-table-column prop="id" label="信息id"> </el-table-column>
        <el-table-column prop="fruitName" label="果实名称"> </el-table-column>
        <el-table-column prop="fruitNum" label="果实数量"> </el-table-column>
        <el-table-column prop="imgCount" label="识别处理后的图片">
          <template slot-scope="{ row }">
            <el-image :src="row.imgCount" :preview-src-list="srcList" style="width: 100px; height: 100px" @click="srcList.push(row.imgCount)"/>
          </template>
        </el-table-column>
        <el-table-column prop="ripeNum" label="果实成熟数量"> </el-table-column>
        <el-table-column prop="imgRipe" label="成熟果实的图片">
          <template slot-scope="{ row }">
            <el-image :src="row.imgRipe" :preview-src-list="srcList2" style="width: 100px; height: 100px" @click="srcList2.push(row.imgRipe)"/>
          </template>
        </el-table-column>
        <el-table-column prop="createTime" label="操作时间"> </el-table-column>
        <el-table-column label="操作">
          <template slot-scope="{ row }">
            <el-button
              size="mini"
              type="danger"
              @click="deleteIdentify(row)"
              icon="el-icon-delete"
              >删除</el-button
            >
          </template>
        </el-table-column>
      </el-table>
      <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
    -->
      <el-pagination
        style="margin-top: 20px; textalign: center"
        :current-page="page"
        :page-sizes="[5, 10, 15]"
        :page-size="pageSize"
        :total="total"
        @current-change="getPageList"
        @size-change="handleSizeChange"
        layout="prev, pager, next, jumper,->, sizes, total"
      >
      </el-pagination>
    </el-card>
  </div>
</template>

<script>
import { IdentifyList, DeleteIdentify } from "@/api/identifyMG";
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "identify",
  data() {
    return {
      // 放大预览图片
      srcList: [],
      srcList2: [],
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 5,
      total: 0,
      list: [],
    };
  },
  mounted() {
    this.getPageList();
  },
  methods: {
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      IdentifyList(page, pageSize)
        .then((res) => {
          console.log("list",res);
          console.log("图片",res.data.records.imgCount)
          console.log("图片",res.data.records.imgRipe)
          if (res.code == 1) {
            this.list = res.data.records;
            //分页赋值
            this.total = res.data.total;
          } else {
            this.$message({
              type: "info",
              message: res.data,
            });
          }
        })
        .catch((err) => {
          this.$message.error("加载失败，请稍后重试");
        });
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 删除操作
    deleteIdentify(row) {
      // 弹框
      this.$confirm(`确定删除信息${row.id}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          // console.log(row.id);
          DeleteIdentify(row.id)
            .then((res) => {
              // console.log(res);
              if (res.code == 1) {
                this.$message({
                  type: "success",
                  message: "识别信息已删除!",
                });
                //再次获取列表数据
                this.getPageList(
                  this.list.length > 1 ? this.page : this.page - 1
                );
              } else {
                this.$message({
                  type: "info",
                  message: res.msg,
                });
              }
            })
            .catch((err) => {
              this.loading = false;
              this.$message.error("识别信息删除失败，请稍后再试！");
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
  },
};
</script>

<style>
</style>


