<template>
  <div>
    <!-- 面包屑导航 -->
    <el-breadcrumb
      separator-class="el-icon-arrow-right"
      style="padding-bottom: 20px"
    >
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">采摘未完成信息</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height:80px">
      <el-form :inline="true" class="demo-form-inline">
        <el-form-item label="查询用户">
          <el-input placeholder="输入用户名称" v-model="selectName"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect1">查询</el-button>
        </el-form-item>
        <el-form-item label="查询通知">
          <el-input placeholder="输入通知名称" v-model="selectTitle"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect2">查询</el-button>
          <el-button type="primary" @click="reload">刷新页面</el-button>
        </el-form-item>
        <!-- 添加按钮 -->
        <el-button
          type="primary"
          icon="el-icon-plus"
          style="float: right"
          @click="showDialog"
          >发布任务</el-button
        >
      </el-form>
    </el-card>
    <!-- 表格数据 -->
    <el-table :data="list" border style="width: 100%">
      <el-table-column prop="title" label="通知"> </el-table-column>
      <el-table-column prop="content" label="通知信息"> </el-table-column>
      <el-table-column prop="empName" label="接收者"> </el-table-column>
      <el-table-column prop="createTime" label="通知发布时间"> </el-table-column>
      <el-table-column prop="updateTime" label="通知更新时间"> </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="{ row }">
          <!-- <el-button size="mini" @click="updatePick(row)" icon="el-icon-edit"
            >修改</el-button
          > -->
          <el-button
            size="mini"
            type="danger"
            @click="deletePick(row)"
            icon="el-icon-delete"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
    -->
    <el-pagination
      style="margin-top: 20px; textalign: center"
      :current-page="page"
      :page-sizes="[5, 10, 15]"
      :page-size="pageSize"
      :total="total"
      @current-change="getPageList"
      @size-change="handleSizeChange"
      layout="prev, pager, next, jumper,->, sizes, total"
    >
    </el-pagination>

    <!-- dialog弹出框 -->
    <el-dialog
      :title="Form.id ? '修改通知' : '发布通知'"
      :visible.sync="dialogFormVisible"
    >
      <el-form style="width: 80%" :model="Form" :rules="rules" ref="ruleForm">
        <el-form-item label="接收人" prop="empId">
          <el-select v-model="Form.empId" placeholder="请选择">
            <el-option
              :label="opt.name"
              :value="opt.id"
              v-for="(opt, index) of adminList"
              :key="index"
            ></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="通知" prop="title">
          <el-input autocomplete="off" v-model="Form.title"></el-input>
        </el-form-item>
        <el-form-item label="通知信息" prop="content">
          <el-input
            type="textarea"
            autocomplete="off"
            v-model="Form.content"
          ></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="addOrUpdatePick">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import { noPickList, DeletePick, noSelectByName, noSelectByTitle, PickPost } from '@/api/pickMG';
import { EmployeeList, AreaAdmin } from '@/api/employeeMG';
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "nopick",
  data() {
    return {
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 10,
      total: 0,
      // 信息展示列表
      datalist: [],
      list: [],
      // 管理人员列表
      adminList: [],
      // 人员信息列表
      userList: [],
      // 查询时转换的id
      tempId: '',
      // 弹出框显示隐藏
      dialogFormVisible: false,
      codeDialog: false,
      // 筛选框数据的id
      selectName: "",
      selectTitle: "",
      Form: {
        title: "",
        content: "",
        empId: "",
      },
      // 表单验证规则
      rules: {
        title: [
          { required: true, message: "请输入通知标题", trigger: "blur" },
        ],
        content: [
          { required: true, message: "请输入通知内容", trigger: "blur" },
        ],
      }
    };
  },
  mounted() {
    this.getUserList();
    this.getAdmin();
    this.getPageList();
  },
  methods: {
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      noPickList(page, pageSize)
        .then((res) => {
          // console.log("List", res);
          if (res.code == 1) {
            this.list =res.data.records;
            // console.log(this.list);
            //分页赋值
            this.total = res.data.total;
          } else {
            this.$message({
              type: "info",
              message: res.data,
            });
          }
        })
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 点击添加按钮
    showDialog() {
      this.dialogFormVisible = true;
      // 清除数据
      this.Form = { areaId: "", type: "" };
      this.getAdmin()
    },
    // 修改某个品牌
    updatePick(row) {
      this.dialogFormVisible = true;
      //将已有信息给对话框
      this.Form = { ...row };
    },
    // 发布任务通知
    addOrUpdatePick() {
      // 当全部字段通过，再去进行请求
      this.$refs.ruleForm.validate((success) => {
        if (success) {
          PickPost(this.Form).then((res) => {
            // console.log("form", this.Form);
            // console.log("add", res);
            this.dialogFormVisible = false;
            if (res.data.code == 1) {
              this.$message({
                type: "success",
                message: "发布通知信息成功",
              });
              this.getPageList(this.Form.id ? this.page : 1);
            } else {
              this.$message({
                type: "warning",
                message: res.data.msg,
              });
            }
          });
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 删除操作
    deletePick(row) {
      // 弹框
      this.$confirm(`确定删除${row.title}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          // console.log(row.id);
          DeletePick(row.id)
            .then((res) => {
              // console.log(res);
              if (res.code == 1) {
                this.$message({
                  type: "success",
                  message: "通知已删除!",
                });
                //再次获取列表数据
                this.getPageList(
                  this.list.length > 1 ? this.page : this.page - 1
                );
              } else {
                this.$message({
                  type: "info",
                  message: res.msg,
                });
              }
            })
            .catch((err) => {
              this.loading = false;
              this.$message.error("通知删除失败，请稍后再试！");
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },

    // 查询操作
    // 根据用户名称查询
    getSelect1() {
      // console.log("selectName", this.selectName);
      if (this.selectName) {
        // console.log(this.adminList);
        for(var i = 0; i < this.userList.length; i++){
          if(this.selectName == this.userList[i].name){
            this.tempId = this.userList[i].id
          }
        }
        noSelectByName(this.tempId, 1, 999)
          .then((res) => {
            // console.log("res",res);
            if (res.success == false) {
              this.$message({
                type: "info",
                message: res.data,
              });
            } else {
              if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
              this.list = res.data.records;
              this.total = res.data.total;
              // console.log(this.list);
            }
          })
      } else {
        this.getPageList();
      }
    },
    // 根据通知查询
    getSelect2() {
      // console.log("selectTitle", this.selectTitle);
      if (this.selectTitle) {
        noSelectByTitle(this.selectTitle, 1, 999)
          .then((res) => {
            // console.log(res);
            if (res.code == 1) {
              if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
              this.list = res.data.records;
              this.total = res.data.total;
              // console.log(this.list);
            } else {
              this.$message({
                type: "info",
                message: res.data,
              });
            }
          })
      } else {
        this.getPageList();
      }
    },
    SelectOn() {
      this.reload();
    },
    // 负责人展示列表
    getAdmin() {
      AreaAdmin().then((res) => {
        if(res.code == 1) {
          this.adminList = res.data;
          // console.log(this.adminList);
        }
      })
    },
    // 获取人员信息展示列表
    getUserList(page = 1, pageSize = 999) {
      EmployeeList(page, pageSize)
        .then((res) => {
          // console.log(res.data);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            this.userList = res.data.records;
            // this.userTotal = res.data.total;
            // console.log('userlist',this.userList);
          }
        })
        .catch((err) => {
          this.$message.error("加载失败，请稍后重试");
        });
    },

  },
};
</script>

<style>
</style>


