import axios from 'axios';
import { req } from './axiosFun';

// 获取信息列表
export const CameraList = (page,pageSize) => { return req("get", "/camera?page="+page+"&pageSize="+pageSize) };

// 添加和修改信息
export const AddOrUpdateCamera = (camera) => {
    if(camera.id){
        return axios.put("/camera", camera)
    } else { 
        return axios.post("/camera", camera)
    }
}

// 删除信息
export const DeleteCamera = (id) => { return axios.delete("/camera/" + id ).then(res => res.data) };

// 根据id查找信息
// export const SelectById = (id) => { return axios.get("/camera/" + id).then(res => res.data)}
export const SelectById = (id,page,pageSize) => { return axios.get("/camera?id="+id+"&page="+page+"&pageSize="+pageSize).then(res => res.data)}


// 抓拍功能
export const TakePhoto = () => { return req("get", "/camera/takePhoto").then(res => res.data)}

// 照片上传功能
export const upload = (data) => { return axios.post("/identify/urlIdentify", data) }

// 根据摄像头id获取果树列表
export const getTreeId = (id) => { return req("get", "/camera/getTreeIdByArea?cid=" + id) }


