/**
* 左边菜单
*/ 
<template>
  <el-menu
    default-active="2"
    :collapse="collapsed"
    collapse-transition
    router
    :default-active="$route.path"
    unique-opened
    class="el-menu-vertical-demo"
    background-color=rgba(0,0,0,0.5)
    text-color="#cde6c7"
    active-text-color="#7fb80e"
  >
    <div class="logobox">
      <img class="logoimg" src="../assets/img/logo.png" alt="" />
    </div>
    <el-submenu
      v-for="menu in allmenu"
      :key="menu.menuid"
      :index="menu.menuname"
    >
      <template slot="title">
        <i class="iconfont" :class="menu.icon"></i>
        <span>{{ menu.menuname }}</span>
      </template>
      <el-menu-item-group>
        <el-menu-item
          v-for="chmenu in menu.menus"
          :index="'/' + chmenu.url"
          :key="chmenu.menuid"
        >
          <i class="iconfont" :class="chmenu.icon"></i>
          <span>{{ chmenu.menuname }}</span>
        </el-menu-item>
      </el-menu-item-group>
    </el-submenu>
  </el-menu>
</template>
<script>
export default {
  name: "leftnav",
  data() {
    return {
      collapsed: false,
      allmenu: [],
    };
  },
  // 创建完毕状态(里面是操作)
  created() {
    let res = {
      success: true,
      data: [
        {
          menuid: 1,
          icon: "li-icon-xiangmuguanli",
          menuname: "摄像机管理",
          hasThird: null,
          url: null,
          menus: [
            {
              menuid: 2,
              icon: null,
              menuname: "摄像机管理",
              hasThird: "N",
              url: "camera/index",
              menus: [null],
            },
          ],
        },
        {
          menuid: 3,
          icon: "icon-order-manage",
          menuname: "识别信息管理",
          hasThird: null,
          url: null,
          menus: [
            {
              menuid: 4,
              icon: null,
              menuname: "识别信息管理",
              hasThird: "N",
              url: "identify/index",
              menus: [null],
            },
          ],
        },
        {
          menuid: 5,
          icon: "li-icon-xitongguanli",
          menuname: "区块果蔬信息管理",
          hasThird: null,
          url: null,
          menus: [
            {
              menuid: 6,
              icon: null,
              menuname: "区管理",
              hasThird: "N",
              url: "blocks/area/index",
              menus: [null],
            },
            {
              menuid: 7,
              icon: null,
              menuname: "果蔬管理",
              hasThird: "N",
              url: "blocks/piece/index",
              menus: [null],
            },
          ],
        },
        {
          menuid: 10,
          icon: "icon-cs-manage",
          menuname: "采摘信息管理",
          hasThird: null,
          url: null,
          menus: [
            {
              menuid: 11,
              icon: null,
              menuname: "采摘完成信息",
              hasThird: "N",
              url: "dopick/pick/index",
              menus: [null],
            },
            {
              menuid: 12,
              icon: null,
              menuname: "预采摘信息",
              hasThird: "N",
              url: "dopick/nopick/index",
              menus: [null],
            },
          ],
        },
        {
          menuid: 8,
          icon: "icon-cus-manage",
          menuname: "人员信息管理",
          hasThird: null,
          url: null,
          menus: [
            {
              menuid: 9,
              icon: null,
              menuname: "人员信息管理",
              hasThird: "N",
              url: "employee/index",
              menus: [null],
            },
          ],
        },
      ],
      msg: "success",
    };
    this.allmenu = res.data;

    // menu(localStorage.getItem('logintoken'))
    //   .then(res => {
    //     console.log(JSON.stringify(res))
    //     if (res.success) {
    //       this.allmenu = res.data
    //     } else {
    //       this.$message.error(res.msg)
    //       return false
    //     }
    //   })
    //   .catch(err => {
    //     this.$message.error('菜单加载失败，请稍后再试！')
    //   })
    // 监听
    this.$root.Bus.$on("toggle", (value) => {
      this.collapsed = !value;
    });
  },
};
</script>
<style>
.el-menu-vertical-demo:not(.el-menu--collapse) {
  width: 240px;
  min-height: 400px;
}
.el-menu-vertical-demo:not(.el-menu--collapse) {
  border: none;
  text-align: left;
}
.el-menu-item-group__title {
  padding: 0px;
}
.el-menu-bg {
  background-color: #00a6ac !important;
}
.el-menu {
  border: none;
}
.logobox {
  height: 40px;
  line-height: 40px;
  background-color: rgba(0,0,0,0.5);
  font-size: 20px;
  text-align: center;
  padding: 20px 0px;
}
.logoimg {
  height: 40px;
}
</style>


