<template>
  <div>
    <!-- 面包屑导航 -->
    <el-breadcrumb
      separator-class="el-icon-arrow-right"
      style="padding-bottom: 20px"
    >
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">采摘完成信息</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height:80px">
      <el-form :inline="true" class="demo-form-inline">
        <el-form-item label="查询用户">
          <el-input placeholder="输入用户名称" v-model="selectName"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect1">查询</el-button>
        </el-form-item>
        <el-form-item label="查询通知">
          <el-input placeholder="输入通知名称" v-model="selectTitle"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect2">查询</el-button>
          <el-button type="primary" @click="reload">刷新页面</el-button>
        </el-form-item>
      </el-form>
    </el-card>
    <!-- 表格数据 -->
    <el-table :data="list" border style="width: 100%">
      <el-table-column prop="title" label="任务通知"> </el-table-column>
      <el-table-column prop="content" label="任务通知信息"> </el-table-column>
      <el-table-column prop="empName" label="接收者"> </el-table-column>
      <el-table-column prop="createTime" label="任务发布时间"> </el-table-column>
      <el-table-column prop="updateTime" label="任务更新时间"> </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="{ row }">
          <el-button
            size="mini"
            type="danger"
            @click="deletePick(row)"
            icon="el-icon-delete"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
    -->
    <el-pagination
      style="margin-top: 20px; textalign: center"
      :current-page="page"
      :page-sizes="[5, 10, 15]"
      :page-size="pageSize"
      :total="total"
      @current-change="getPageList"
      @size-change="handleSizeChange"
      layout="prev, pager, next, jumper,->, sizes, total"
    >
    </el-pagination>

  </div>
</template>

<script>
import { PickList, DeletePick, SelectByName, SelectByTitle, } from '@/api/pickMG';
import { EmployeeList } from '@/api/employeeMG';
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "pick",
  data() {
    return {
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 10,
      total: 0,
      list: [],
      userList: [],
      selectList: [],
      tempId: '',
      // 筛选框数据的id
      selectName: "",
      selectTitle: "",
      Form: {
        areaId: "",
        type: "",
      },
    };
  },
  mounted() {
    this.getUserList();
    this.getPageList();
  },
  methods: {
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      PickList(page, pageSize)
        .then((res) => {
          // console.log("List", res);
          if (res.code == 1) {
            this.list = res.data.records;
            // console.log(this.list);
            //分页赋值
            this.total = res.data.total;
          } else {
            this.$message({
              type: "info",
              message: res.data.msg,
            });
          }
        })
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 删除操作
    deletePick(row) {
      // 弹框
      this.$confirm(`确定删除${row.title}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          // console.log(row.id);
          DeletePick(row.id)
            .then((res) => {
              // console.log(res);
              if (res.code == 1) {
                this.$message({
                  type: "success",
                  message: "果蔬信息已删除!",
                });
                //再次获取列表数据
                this.getPageList(
                  this.list.length > 1 ? this.page : this.page - 1
                );
              } else {
                this.$message({
                  type: "info",
                  message: res.msg,
                });
              }
            })
            .catch((err) => {
              this.loading = false;
              this.$message.error("采摘完成信息删除失败，请稍后再试！");
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },

    // 查询操作
    // 根据用户名称查询
    getSelect1() {
      // console.log("selectName", this.selectName);
      if (this.selectName) {
        // console.log(this.userList);
        for(var i = 0; i < this.userList.length; i++){
          if(this.selectName == this.userList[i].name){
            this.tempId = this.userList[i].id
          }
        }
        SelectByName(this.tempId, 1, 999)
          .then((res) => {
            // console.log(this.tempId);
            if (res.success == false) {
              this.$message({
                type: "info",
                message: res.data,
              });
            } else {
              if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
              this.list = res.data.records;
              this.total = res.data.total;
              // console.log(this.list);
            }
          })
      } else {
        this.getPageList();
      }
    },
    // 通知查询
    getSelect2() {
      this.list = undefined;
      this.list = new Array();
      // console.log("selectTitle", this.selectTitle);
      if (this.selectTitle) {
        SelectByTitle(this.selectTitle, 1, 999)
          .then((res) => {
            // console.log(res);
            if (res.code == 1) {
              if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
              this.list = res.data.records;
              this.total = res.data.total;
              // console.log(this.list);
            } else {
              this.$message({
                type: "info",
                message: res.data,
              });
            }
          })
      } else {
        this.getPageList();
      }
    },
    SelectOn() {
      this.reload();
    },
    // 获取人员信息展示列表
    getUserList(page = 1, pageSize = 999) {
      EmployeeList(page, pageSize)
        .then((res) => {
          // console.log(res.data);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            this.userList = res.data.records;
            // this.userTotal = res.data.total;
            // console.log('userlist',this.userList);
          }
        })
        .catch((err) => {
          this.$message.error("加载失败，请稍后重试");
        });
    },

  },
};
</script>

<style>
</style>


