import axios from 'axios';
import { loginreq, req } from './axiosFun';

// 获取区信息列表
export const AreaList = (page,pageSize) => { return req("get", "/area?page="+page+"&pageSize="+pageSize) };


// 添加和修改信息
export const AddOrUpdateArea = (area) => {
    if(area.id){
        return axios.put("/area", area)
    } else { 
        return axios.post("/area", area)
    }
}


//删除信息
export const DeleteArea = (params) => { return axios.delete("/area/" + params ).then(res => res.data) };

// 根据区名查找信息
export const SelectByName = (name,page,pageSize) => { return axios.get("/area?page="+page+"&pageSize="+pageSize+"&name="+name).then(res => res.data)}


