import axios from 'axios';
import { loginreq, req } from './axiosFun';

// 获取信息列表
export const EmployeeList = (page,pageSize) => { return req("get", "/employee/page?page="+page+"&pageSize="+pageSize) };


// 添加人员
export const EmployeeAdd = (employee) => {return axios.post("/employee", employee)}
// 修改人员
export const EmployeeUpdate = (employee) => {return axios.put("/employee", employee)}


//删除信息
export const DeleteEmployee = (id) => { return axios.delete("/employee/" + id ).then(res => res.data) };

// 根据人员名称查找信息
export const SelectByName = (name,page,pageSize) => { return axios.get("/employee/page?name="+name+"&page="+page+"&pageSize="+pageSize).then(res => res.data)}

// 查询园区负责人
export const AreaAdmin = (params) => { return req("get", "/employee/getAdmin", params)}


