import axios from 'axios';
import { loginreq, req } from './axiosFun';

// 获取未完成通知信息列表
export const noPickList = (page,pageSize) => { return req("get", "/pickInfo/getNoFinish?page="+page+"&pageSize="+pageSize) };
// 获取完成通知信息列表
export const PickList = (page,pageSize) => { return req("get", "/pickInfo/getFinish?page="+page+"&pageSize="+pageSize) };

// 发送消息通知
export const PickPost = (info) => {
    if(info.id){
        return axios.put("/pickInfo", info)
    } else { 
        return axios.post("/pickInfo", info) 
    }
}

// 删除信息
export const DeletePick = (id) => { return axios.delete("/pickInfo/" + id ).then(res => res.data) };

// 查询未完成通知信息
export const noSelectByName = (name,page,pageSize) => { return axios.get("/pickInfo/getNoFinish?empId="+name+"&page="+page+"&pageSize="+pageSize).then(res => res.data)}

export const noSelectByTitle = (title,page,pageSize) => { return axios.get("/pickInfo/getNoFinish?page="+page+"&pageSize="+pageSize+"&title="+title).then(res => res.data)}
// 查询完成通知信息
export const SelectByName = (name,page,pageSize) => { return axios.get("/pickInfo/getFinish?empId="+name+"&page="+page+"&pageSize="+pageSize).then(res => res.data)}

export const SelectByTitle = (title,page,pageSize) => { return axios.get("/pickInfo/getFinish?page="+page+"&pageSize="+pageSize+"&title="+title).then(res => res.data)}


