<template>
  <div>
    <!-- 面包屑导航 -->
    <el-breadcrumb
      separator-class="el-icon-arrow-right"
      style="padding-bottom: 20px"
    >
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">摄像机管理</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height: 80px">
      <el-form :inline="true" class="demo-form-inline">
        <el-form-item label="摄像机编号">
          <el-input
            placeholder="输入摄像机编号"
            v-model="selectName"
          ></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect">查询</el-button>
          <el-button type="primary" @click="reload">刷新页面</el-button>
          <!-- <el-button type="danger" @click="toggleSelection()">取消选择</el-button> -->
        </el-form-item>
        <!-- 添加按钮 -->
        <el-button
          type="primary"
          icon="el-icon-plus"
          style="float: right"
          @click="showDialog"
          >添加摄像头</el-button
        >
      </el-form>
    </el-card>

    <!-- 表格数据 -->
    <el-table
      :data="list"
      border
      @selection-change="handleSelectionChange"
      ref="multipleTable"
      lazy
    >
      <!-- <el-table-column type="selection" width="55"></el-table-column> -->
      <el-table-column prop="id" label="摄像头编号"> </el-table-column>
      <el-table-column prop="areaId" label="对应区以及id">
      </el-table-column>
      <!-- <el-table-column prop="logoUrl" label="对应果蔬">
        <template slot-scope="{ row }">
          <img :src="row.logoUrl" alt="" style="width: 50px; height: 50px" />
        </template>
      </el-table-column> -->
      <el-table-column prop="updateTime" label="最近一次更新时间">
      </el-table-column>
      <el-table-column prop="createUser" label="创建者"></el-table-column>
      <el-table-column prop="updateUser" label="修改者"></el-table-column>
      <el-table-column label="摄相机抓拍">
        <el-button @click="takePhoto" type="warning" size="mini">点击抓拍</el-button>
      </el-table-column>
      <!-- 图片上传 -->
      <el-table-column label="抓拍图片上传">
        <template slot-scope="{ row }">
          <el-button size="mini" @click="cameraUpload(row)">图片上传</el-button>
        </template>
      </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="{ row }">
          <el-button size="mini" @click="updateCamera(row)" icon="el-icon-edit"
            >修改</el-button
          >
          <el-button
            size="mini"
            type="danger"
            @click="deleteCamera(row)"
            icon="el-icon-delete"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
        current-page:当前第几页
        page-size:当前页需要展示的数据条数
    -->
    <el-pagination
      style="margin-top: 20px; textalign: center"
      :current-page="page"
      :page-sizes="[5, 10, 15]"
      :page-size="pageSize"
      :total="total"
      @current-change="getPageList"
      @size-change="handleSizeChange"
      layout="prev, pager, next, jumper,->, sizes, total"
    >
    </el-pagination>

    <!-- dialog弹出框 -->
    <el-dialog
      :title="Form.id ? '修改摄像头信息' : '添加摄像头信息'"
      :visible.sync="dialogFormVisible"
    >
      <el-form style="width: 80%" :model="Form" :rules="rules" ref="ruleForm">
        <!-- <el-form-item label="摄像头编号" prop="id">
          <el-input autocomplete="off" v-model="Form.id"></el-input>
        </el-form-item> -->
        <el-form-item label="对应区的id" prop="areaId">
          <el-input autocomplete="off" v-model="Form.areaId"></el-input>
        </el-form-item>
        <!-- <el-form-item label="添加者" prop="createUser">
          <el-input autocomplete="off" v-model="Form.createUser"></el-input>
        </el-form-item> -->
        <!-- <el-form-item label="修改者" prop="updateUser">
          <el-input autocomplete="off" v-model="Form.updateUser"></el-input>
        </el-form-item> -->
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="addOrUpdateCamera" @keyup.enter="keyDown(e)">确 定</el-button>
      </div>
    </el-dialog>

    <!-- 图片上传弹出框 -->
    <el-dialog title="抓拍图片上传" :visible.sync="dialogFormVisible2">
      <el-form
        style="width: 80%"
        :model="tForm"
        :rules="trules"
        ref="tRuleForm"
      >
        <el-form-item label="果蔬编号" prop="id">
          <el-select v-model="tForm.id" placeholder="请选择果蔬编号">
            <el-option
              :label="opt"
              :value="opt"
              v-for="(opt, index) of treeList"
              :key="index"
            ></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="图片上传" prop="img">
          <el-upload
            class="avatar-uploader"
            action="/identify/img2url"
            :show-file-list="false"
            :on-success="handleAvatarSuccess"
            :before-upload="beforeAvatarUpload"
          >
            <img v-if="tForm.img" :src="tForm.img" class="avatar" />
            <i v-else class="el-icon-plus avatar-uploader-icon"></i>
          </el-upload>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible2 = false">取 消</el-button>
        <el-button type="primary" @click="Upload">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import {
  CameraList,
  AddOrUpdateCamera,
  DeleteCamera,
  SelectById,
  upload,
  getTreeId
} from "@/api/cameraMG";
import { EmployeeList } from "@/api/employeeMG";
import { AreaList, } from '@/api/areaMG';
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "camera",
  data() {
    // 自定义校验规则
    var validateareaId = (rule, value, callback) => {
      if (value.length < 1 || value.length > 10) {
        callback(new Error("请输入正确的区号:1-10位"));
      } else {
        callback();
      }
    };
    return {
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 10,
      total: 0,
/*       userTotal: 0,
      areaTotal: 0, */
      // 摄像机信息列表
      list: [],
      // 人员信息列表
      userList: [],
      // 果蔬编号列表
      treeList: [],
      // 区名列表
      areaList: [],
      // 选择状态
      multipleSelection: [],
      // 弹出框
      dialogFormVisible: false,
      dialogFormVisible2: false,
      // 筛选框数据的id
      selectName: "",
      // 收集信息
      Form: {
        id: "",
        areaId: "",
        createUser: "",
        updateUser: "",
      },
      tForm: {
        treeId: "",
        img: "",
      },
      // 表单验证规则
      rules: {
        areaId: [
          { required: true, message: "请输入对应区的id", trigger: "blur" },
          { validator: validateareaId, trigger: "change" },
        ],
      },
      trules: {
        id: [{ required: true, message: "请选择对应果蔬的id", trigger: "change" }],
        img: [{ required: true, message: "请选择上传图片", trigger: "change" }],
      },
    };
  },
  // 页面初加载
  mounted() {
    // 获取人员信息列表
    this.getUserList();
    // 获取区信息列表
    this.getAreaList();
    // 获取信息列表
    this.getPageList();
        // 绑定监听事件
    window.addEventListener("keydown",this.keyDown);
  },
  destroyed() {
    // 销毁事件
    window.removeEventListener("keydown",this.keyDown, false)
  },
  methods: {
    // 获取信息展示列表
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      CameraList(page, pageSize)
        .then((res) => {
          // console.log(res);
          if (res.code == 1) {
            this.list = res.data.records;
            // console.log("list", this.list);
            // 分页赋值
            this.total = res.data.total;
            // 把创建者和修改者从id变成名称
            for (var ci = 0; ci < this.list.length; ci++) {
              for (var pj = 0; pj < this.userList.length; pj++) {
                if (
                  this.list[ci].updateUser == this.userList[pj].id
                ) {
                  this.list[ci].updateUser = this.userList[pj].name;
                  // console.log("配对成功");
                }
                if (
                  this.list[ci].createUser == this.userList[pj].id
                ) {
                  this.list[ci].createUser = this.userList[pj].name;
                  // console.log("配对成功");
                }
              };

              // 把对应区从id改为区名
              for(var aj = 0; aj < this.areaList.length; aj++) {
                if(this.list[ci].areaId == this.areaList[aj].id) {
                  this.list[ci].areaId = this.areaList[aj].name + "：" + this.list[ci].areaId
                }
              }
            }
          } else {
            this.$message({
              type: "info",
              message: res.msg,
            });
          }
        })
        .catch((err) => {
          this.$message.error("加载失败，请稍后重试");
        });
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 点击添加按钮
    showDialog() {
      this.dialogFormVisible = true;
      // 清除数据
      this.Form = { areaId: "" };
    },
    // 修改某个品牌
    updateCamera(row) {
      this.dialogFormVisible = true;
      // 将已有信息给对话框
      this.Form = { ...row };
    },
    // 添加功能的实现
    addOrUpdateCamera() {
      // 当全部字段通过，再去进行请求
      this.$refs.ruleForm.validate((success) => {
        // 把创建者和修改者从名称变成id
        for (var i = 0; i < this.userList.length; i++) {
          if (this.Form.updateUser == this.userList[i].name) {
            this.Form.updateUser = this.userList[i].id;
            // console.log("配对成功");
          }
          if (this.Form.createUser == this.userList[i].name) {
            this.Form.createUser = this.userList[i].id;
            // console.log("配对成功");
          } else {
            this.Form.createUser = "";
          }
        }
        if (success) {
          this.dialogFormVisible = false;
          // console.log(this.Form);
          AddOrUpdateCamera(this.Form).then((res) => {
            // console.log(res);
            if (res.status == 200) {
              this.$message({
                type: "success",
                message: this.Form.id
                  ? "修改摄像机信息成功"
                  : "添加摄像机信息成功",
              });
              this.getPageList(this.Form.id ? this.page : 1);
            } else {
              this.$message({
                type: "warning",
                message: res.data.msg,
              });
            }
          });
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 删除操作
    deleteCamera(row) {
      // 弹框
      this.$confirm(`确定删除 摄像机${row.id}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          // console.log(row.id);
          DeleteCamera(row.id)
            .then((res) => {
              // console.log(res)
              if (res.code == 1) {
                this.$message({
                  type: "success",
                  message: "摄像机信息已删除!",
                });
                //再次获取列表数据
                this.getPageList(
                  this.list.length > 1 ? this.page : this.page - 1
                );
              } else {
                this.$message({
                  type: "info",
                  message: "删除有误",
                });
              }
            })
            .catch((err) => {
              this.loading = false;
              this.$message.error("摄像机信息删除失败，请稍后再试！");
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },

    // 查询操作
    getSelect() {
      // console.log("selectName", this.selectName);
      if (this.selectName) {
        SelectById(this.selectName, 1, 999)
          .then((res) => {
            // console.log(res);
            if (res.code == 1) {
              if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
              // 把查询到的数据赋值到列表
              this.list = res.data.records;
              this.total = res.data.total;
              // 把创建者和修改者从id变成名称
            for (var ci = 0; ci < this.list.length; ci++) {
              for (var pj = 0; pj < this.userList.length; pj++) {
                if (
                  this.list[ci].updateUser == this.userList[pj].id
                ) {
                  this.list[ci].updateUser = this.userList[pj].name;
                  // console.log("配对成功");
                }
                if (
                  this.list[ci].createUser == this.userList[pj].id
                ) {
                  this.list[ci].createUser = this.userList[pj].name;
                  // console.log("配对成功");
                }
              };

              // 把对应区从id改为区名
              for(var aj = 0; aj < this.areaList.length; aj++) {
                if(this.list[ci].areaId == this.areaList[aj].id) {
                  this.list[ci].areaId = this.areaList[aj].name + "：" + this.list[ci].areaId
                }
              }
            }
            } else {
              this.$message({
                type: "info",
                message: res.data,
              });
            }
          })
      } else {
        this.getPageList();
      }
    },

    // 点击抓拍功能
    takePhoto() {
      window.open("http://172.16.1.121/web/admin.html");
    },
    // 点击图片上传功能
    cameraUpload(row) {
      this.tForm = { id: "", img: "" };
      this.dialogFormVisible2 = true;
      this.getTreeid(row);
    },

    // 全选单选功能
    toggleSelection(rows) {
      if (rows) {
        rows.forEach((row) => {
          this.$refs.multipleTable.toggleRowSelection(row);
        });
      } else {
        this.$refs.multipleTable.clearSelection();
      }
    },
    handleSelectionChange(val) {
      this.multipleSelection = val;
    },

    // 获取人员信息展示列表
    getUserList(page = 1, pageSize = 999) {
      EmployeeList(page, pageSize)
        .then((res) => {
          // console.log(res.data);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            this.userList = res.data.records;
            // this.userTotal = res.data.total;
            // console.log('userlist',this.userList);
          }
        })
    },

    // 图片上传成功
    handleAvatarSuccess(res, file) {
      // console.log("img", res);
      // 收集图片数据，将来上传给服务器
      this.tForm.img = res.data;
    },
    // 图片上传之前
    beforeAvatarUpload(file) {
      // console.log(file);
      const isJPG = file.type === "image/jpeg" || file.type === "image/png";

      if (!isJPG) {
        this.$message.error("上传图片只能是 JPG/PNG 格式!");
      }
      return isJPG;
    },

    // 图片弹出框上传
    Upload() {
      // 当全部字段通过，再去进行请求
      this.$refs.tRuleForm.validate((success) => {
        if (success) {
          const loading = this.$loading({
            lock: true,
            text: '图片上传中',
            spinner: 'el-icon-loading',
            background: 'rgba(0, 0, 0, 0.7)'
          });
          this.dialogFormVisible2 = false;
          // console.log(this.Form);
          upload(this.tForm).then((res) => {
            // console.log(res);
            if (res.data.code == 1) {
              loading.close();
              this.$message({
                type: "success",
                message: "图片上传成功",
              });
              this.getPageList();
            } else {
              this.$message({
                type: "warning",
                message: "上传失败，请联系相关人员",
              });
            }
          });
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 获取果蔬编号
    getTreeid(row) {
      // console.log(row);
      getTreeId(row.id)
      .then((res) => {
        // console.log(res);
        if(res.code == 1) {
          this.treeList = res.data;
          // console.log("treelist",this.treeList);
        }
      })
    },
    // 获取区信息
    getAreaList(page = 1, pageSize = 999) {
      AreaList(page, pageSize)
        .then((res) => {
          // console.log(res.data);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            this.areaList = res.data.records;
            this.areaTotal = res.data.total;
            // console.log('arealist',this.areaList);
          }
        })
    },
    // 点击回车提交 enter键的ASCII是13
    keyDown(e) {
      if(e.keyCode == 13) {
        this.addOrUpdateCamera();
      }
    }
  },
};
</script>

<style>
.avatar-uploader .el-upload {
  border: 1px dashed #d9d9d9;
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
.avatar-uploader .el-upload:hover {
  border-color: #409eff;
}
.avatar-uploader-icon {
  font-size: 28px;
  color: #8c939d;
  width: 178px;
  height: 178px;
  line-height: 178px;
  text-align: center;
}
.avatar {
  width: 178px;
  height: 178px;
  display: block;
}
</style>


