<template>
  <div>
    <!-- 面包屑导航 -->
    <el-breadcrumb
      separator-class="el-icon-arrow-right"
      style="padding-bottom: 20px"
    >
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">果蔬信息管理</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height:80px">
      <el-form :inline="true" class="demo-form-inline">
        <el-form-item label="果蔬类型">
          <el-input placeholder="输入果蔬名称" v-model="selectName"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect">查询</el-button>
          <el-button type="primary" @click="reload">刷新页面</el-button>
        </el-form-item>
        <!-- 添加按钮 -->
        <el-button
          type="primary"
          icon="el-icon-plus"
          style="float: right"
          @click="showDialog"
          >添加果蔬</el-button
        >
      </el-form>
    </el-card>
    <!-- 表格数据 -->
    <el-table :data="list" border style="width: 100%">
      <el-table-column prop="areaName" label="区名"> </el-table-column>
      <el-table-column prop="id" label="果蔬id"> </el-table-column>
      <el-table-column prop="typen" label="果蔬类型"> </el-table-column>
      <el-table-column prop="countNum" label="果实数"> </el-table-column>
      <el-table-column prop="ripeNum" label="果实成熟数"> </el-table-column>
      <el-table-column prop="img" label="图片">
        <template slot-scope="{ row }">
          <el-image :src="row.img" :preview-src-list="srcList" style="width: 100px; height: 100px" @click="srcList.push(row.img)"/>
        </template>
      </el-table-column>
      <el-table-column prop="code" label="二维码">
        <template slot-scope="{ row }">
          <el-button size="mini" @click="getCode(row)">生成二维码</el-button>
        </template>
      </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="{ row }">
          <el-button size="mini" @click="updatePiece(row)" icon="el-icon-edit"
            >修改</el-button
          >
          <el-button
            size="mini"
            type="danger"
            @click="deletePiece(row)"
            icon="el-icon-delete"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
    -->
    <el-pagination
      style="margin-top: 20px; textalign: center"
      :current-page="page"
      :page-sizes="[5, 10, 15]"
      :page-size="pageSize"
      :total="total"
      @current-change="getPageList"
      @size-change="handleSizeChange"
      layout="prev, pager, next, jumper,->, sizes, total"
    >
    </el-pagination>

    <!-- dialog弹出框 -->
    <!-- 添加果蔬弹框 -->
    <el-dialog
      :title="Form.id ? '修改果蔬信息' : '添加果蔬信息'"
      :visible.sync="dialogFormVisible"
    >
      <el-form style="width: 80%" :model="Form" :rules="rules" ref="ruleForm">
        <el-form-item label="区号" prop="areaId">
          <el-input autocomplete="off" v-model="Form.areaId"></el-input>
        </el-form-item>
        <el-form-item label="果蔬类型" prop="type">
          <el-select v-model="Form.type" placeholder="请选择果蔬类型">
            <el-option
              :label="opt.type"
              :value="opt.id"
              v-for="(opt, index) of selectList"
              :key="index"
            ></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="addOrUpdatePiece">确 定</el-button>
      </div>
    </el-dialog>

    <!-- 二维码信息弹框 -->
    <el-dialog title="二维码" :visible.sync="codeDialog" @opened="showCode">
      <div class="qrcode" ref="qrCodeUrl"></div>
      <div slot="footer" class="dialog-footer">
        <el-button type="primary" @click="codeDialog = false">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
// 二维码组件
import QRCode from "qrcodejs2";

import {
  PieceList,
  DeletePiece,
  AddOrUpdatePiece,
  GetType,
  SelectByType,
} from "@/api/pieceMG";
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "piece",
  data() {
    // 自定义校验规则
    var validateId = (rule, value, callback) => {
      if (value.length < 1 || value.length > 10) {
        callback(new Error("请输入正确的号码:1-10位"));
      } else {
        callback();
      }
    };
    return {
      // 放大预览图列表
      srcList: [],
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 5,
      total: 0,
      // 表格数据列表
      list: [],
      // 下拉选择框
      selectList: [],
      codeId: "",
      // 弹出框显示隐藏
      dialogFormVisible: false,
      codeDialog: false,
      // 查询参数
      selectName: "",
      Form: {
        areaId: "",
        type: "",
      },
      // 表单验证规则
      rules: {
        areaId: [
          { required: true, message: "请输入区号", trigger: "blur" },
          { validator: validateId, trigger: "change" },
        ],
        type: [
          { required: true, message: "请选择果蔬类型", trigger: "change" },
        ],
      },
    };
  },
  mounted() {
    this.getTypeList();
    this.getPageList();
    // this.getCode();
  },
  methods: {
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      PieceList(page, pageSize)
        .then((res) => {
          // console.log("List", res.data);
          if (res.success == false) {
            this.$message({
              type: "info",
              message: res.data,
            });
          } else {
            this.list = res.data.records;
            //分页赋值
            this.total = res.data.total;
            this.srcList = res.data.records;
            // console.log(this.srcList);
          }
        })
        .catch((err) => {
          this.$message.error("加载失败，请稍后重试");
        });
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 点击添加按钮
    showDialog() {
      this.dialogFormVisible = true;
      // 清除数据
      this.Form = { areaId: "", type: "" };
    },
    // 修改某个果蔬信息
    updatePiece(row) {
      this.dialogFormVisible = true;
      //将已有信息给对话框
      this.Form = { ...row };
    },
    // 添加和修改果蔬功能实现
    addOrUpdatePiece() {
      // 当全部字段通过，再去进行请求
      this.$refs.ruleForm.validate((success) => {
        if (success) {
          AddOrUpdatePiece(this.Form).then((res) => {
            // console.log("form", this.Form);
            // console.log("add", res);
            this.dialogFormVisible = false;
            if (res.data.code == 1) {
              this.$message({
                type: "success",
                message: this.Form.id ? "修改果蔬信息成功" : "添加果蔬信息成功",
              });
              this.getPageList(this.Form.id ? this.page : 1);
            } else {
              this.$message({
                type: "warning",
                message: res.data.msg,
              });
            }
          });
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 删除操作
    deletePiece(row) {
      // 弹框
      this.$confirm(`确定删除 ${row.areaName}:${row.typen}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          // console.log(row.id);
          DeletePiece(row.id)
            .then((res) => {
              // console.log(res);
              if (res.code == 1) {
                this.$message({
                  type: "success",
                  message: "果蔬信息已删除!",
                });
                //再次获取列表数据
                this.getPageList(
                  this.list.length > 1 ? this.page : this.page - 1
                );
              } else {
                this.$message({
                  type: "info",
                  message: res.msg,
                });
              }
            })
            .catch((err) => {
              this.loading = false;
              this.$message.error("果蔬信息删除失败，请稍后再试！");
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },

    // 查询操作
    getSelect() {
      // console.log("selectName", this.selectName);
      if (this.selectName) {
        SelectByType(this.selectName, 1, 999)
          .then((res) => {
            // console.log(res);
            if (res.code == 1) {
              if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
              this.list = res.data.records;
              this.total = res.data.total;
              // console.log(this.list);
            } else {
              this.$message({
                type: "info",
                message: res.data,
              });
            }
          })
      } else {
        this.getPageList();
      }
    },
    SelectOn() {
      this.reload();
    },

    // 获取筛选列表
    getTypeList() {
      GetType().then((res) => {
        if (res.length > 0) {
          this.selectList = res;
        }
      });
    },
    // 生成二维码
    createCode(codeId) {
      // 清除上一张二维码的缓存
      this.$refs.qrCodeUrl.innerHTML = "";
      let qrcode = new QRCode(this.$refs.qrCodeUrl, {
        text: codeId, //  生成二维码的 内容
        width: 200,
        height: 200,
        render: "canvas",
        correctLevel: QRCode.CorrectLevel.H,
      });
    },
    getCode(row) {
      this.codeDialog = true;
      this.codeId = row.id;
    },
    // 展现二维码
    showCode() {
      this.createCode(this.codeId);
    },
  },
};
</script>

<style>
.avatar-uploader .el-upload {
  border: 1px dashed #d9d9d9;
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
.avatar-uploader .el-upload:hover {
  border-color: #409eff;
}
.avatar-uploader-icon {
  font-size: 28px;
  color: #8c939d;
  width: 178px;
  height: 178px;
  line-height: 178px;
  text-align: center;
}
.avatar {
  width: 178px;
  height: 178px;
  display: block;
}
</style>


