import axios from 'axios';
import { loginreq, req } from './axiosFun';

// 获取信息列表
export const IdentifyList = (page,pageSize) => { return req("get", "/identify?page="+page+"&pageSize="+pageSize) };




//删除信息
export const DeleteIdentify = (id) => { return axios.delete("/identify/" + id ).then(res => res.data) };


