<template>
  <div>
        <!-- 面包屑导航 -->
    <el-breadcrumb separator-class="el-icon-arrow-right" style="padding-bottom: 20px">
      <el-breadcrumb-item :to="{ path: '/' }">登录页
      </el-breadcrumb-item>
      <el-breadcrumb-item><div style="color:#fff">区管理</div>
        </el-breadcrumb-item>
    </el-breadcrumb>
    <el-card style="height:80px">
      <el-form :inline="true" class="demo-form-inline">
        <el-form-item label="区名">
          <el-input placeholder="输入区名" v-model="selectName"></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="getSelect">查询</el-button>
          <el-button type="primary" @click="reload">刷新页面</el-button>
        </el-form-item>
        <!-- 添加按钮 -->
        <el-button
          type="primary"
          icon="el-icon-plus"
          style="float: right"
          @click="showDialog"
          >添加区</el-button
        >
      </el-form>
    </el-card>
    <!-- 表格数据 -->
    <el-table :data="list" border>
      <el-table-column prop="id" label="区号"> </el-table-column>
      <el-table-column prop="name" label="区名"> </el-table-column>
      <el-table-column prop="size" label="区块大小(m²)"> </el-table-column>
      <!-- <el-table-column prop="type" label="种植类型"> </el-table-column> -->
      <el-table-column prop="description" label="描述"> </el-table-column>
      <el-table-column prop="updateTime" label="最近一次操作时间">
      </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="{ row }">
          <el-button size="mini" @click="updateArea(row)" icon="el-icon-edit"
            >修改</el-button
          >
          <el-button
            size="mini"
            type="danger"
            @click="deleteArea(row)"
            icon="el-icon-delete"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>
    <!-- 分页器 
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
    -->
    <el-pagination
      style="margin-top: 20px; textalign: center"
      :current-page="page"
      :page-sizes="[5, 10, 15]"
      :page-size="pageSize"
      :total="total"
      @current-change="getPageList"
      @size-change="handleSizeChange"
      layout="prev, pager, next, jumper,->, sizes, total"
    >
    </el-pagination>

    <!-- dialog弹出框 -->
    <el-dialog
      :title="Form.id ? '修改区信息' : '添加区信息'"
      :visible.sync="dialogFormVisible"
    >
      <el-form style="width: 80%" :model="Form" :rules="rules" ref="ruleForm">
        <el-form-item label="区名" prop="name">
          <el-input autocomplete="off" v-model="Form.name"></el-input>
        </el-form-item>
        <el-form-item label="类型" prop="type">
          <el-input autocomplete="off" v-model="Form.type"></el-input>
        </el-form-item>
        <el-form-item label="区块大小" prop="size">
          <el-input autocomplete="off" v-model="Form.size"></el-input>
        </el-form-item>
        <el-form-item label="负责人" prop="empId">
          <el-select v-model="Form.empId" placeholder="请选择">
            <el-option
              :label="opt.name"
              :value="opt.id"
              v-for="(opt, index) of adminList"
              :key="index"
            ></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="区块描述">
          <el-input
            type="textarea"
            autocomplete="off"
            v-model="Form.description"
          ></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogFormVisible = false">取 消</el-button>
        <el-button type="primary" @click="addOrUpdateArea">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import { AreaList, DeleteArea, AddOrUpdateArea, SelectByName } from '@/api/areaMG';
import { AreaAdmin } from '@/api/employeeMG';
export default {
  inject: ["reload"], //  此处引入在app中定义的reload方法
  name: "area",
  data() {
    // 自定义校验规则
    var validateName = (rule, value, callback) => {
      if (value.length < 2 || value.length > 6) {
        callback(new Error("请输入正确的区名:2-6位"));
      } else {
        callback();
      }
    };
    return {
      // 代表当前分页的第几页
      page: 1,
      // 当前页面展示几条数据
      pageSize: 10,
      total: 0,
      list: [],
      adminList: [],
      dialogFormVisible: false,
      // 筛选框数据的id
      selectName: '',
      Form: {
        name: "",
        type: "",
        size: "",
        description: "",
        empId: "",
      },
      // 表单验证规则
      rules: {
        name: [
          { required: true, message: "请输入对应区", trigger: "blur" },
          { validator: validateName, trigger: "change" },
        ],
        type: [
          { required: true, message: "请输入果蔬类型", trigger: "blur" },
        ],
        size: [
          { required: true, message: "请输入区块大小", trigger: "blur" },
        ],
        empId: [
          { required: true, message: "请选择负责人", trigger: "change" },
        ],
      },
    };
  },
  mounted() {
    this.getAdmin();
    this.getPageList();
  },
  methods: {
    getPageList(pager = 1) {
      this.page = pager;
      const { page, pageSize } = this;
      AreaList(page,pageSize)
        .then(res => {
          // console.log('list',res.data);
          if(res.success == false){
            this.$message({
              type: 'info',
              message: res.data.msg
            })
          } else {
            this.list = res.data.records
            //分页赋值
            this.total = res.data.total
          }
        })
        .catch(err => {
          this.$message.error('加载失败，请稍后重试')
        })
    },
    // 某页需要展示的数据发生变化时触发
    handleSizeChange(pageSize) {
      this.pageSize = pageSize;
      this.getPageList();
    },
    // 点击添加按钮
    showDialog() {
      this.dialogFormVisible = true;
      // 清除数据
      this.Form = { name: "", description: "" };
    },
    // 修改某个品牌
    updateArea(row) {
      this.dialogFormVisible = true;
      //将已有信息给对话框
      this.Form = { ...row };
    },
    addOrUpdateArea() {
      // 当全部字段通过，再去进行请求
      this.$refs.ruleForm.validate((success) => {
        if (success) {
          // console.log('thisForm',this.Form);
          AddOrUpdateArea(this.Form)
          .then(res => {
            // console.log("res",res);
            this.dialogFormVisible = false;
            if (res.data.code == 1) {
            this.$message({
              type: "success",
              message: this.Form.id
                ? "修改区信息成功"
                : "添加区信息成功",
            });
            this.getPageList(this.Form.id ? this.page : 1);
          } else {
            this.$message({
              type: 'info',
              message: res.data.msg
            })
          }
          })
        } else {
          console.log("error submit!!");
          return false;
        }
      });
    },
    // 删除操作
    deleteArea(row) {
      // 弹框
      this.$confirm(`确定删除 ${row.name}:${row.id}?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          // console.log(row.id);
          DeleteArea(row.id)
            .then(res => {
              // console.log(res);
              if (res.code == 1) {
                // console.log(this.$message);
                this.$message({
                  type: 'success',
                  message: '区信息已删除!'
                })
                //再次获取列表数据
                this.getPageList(this.list.length > 1 ? this.page : this.page - 1);
                // console.log(this.page);
              } else {
                this.$message({
                  type: 'info',
                  message: '删除有误'
                })
              }
            })
            .catch(err => {
              this.loading = false
              this.$message.error('区信息删除失败，请稍后再试！')
            })
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    // 查询操作
    getSelect() {
      // console.log("selectName", this.selectName);
      if(this.selectName){
        SelectByName(this.selectName, 1, 999)
        .then((res) => {
          // console.log("res.data",res);
          if (res.code == 1) {
            if(res.data.total == 0){
                this.$message({
                  type: "error",
                  message: "未找到此信息",
                });
              }
            this.list = res.data.records;
            this.total = res.data.total;
            // console.log("this.list",this.list);
          } else {
            this.$message({
              type: "info",
              message: res.data.msg,
            });
          }
        })
      } else {
        this.getPageList();
      }
    },

    // 负责人展示列表
    getAdmin() {
      AreaAdmin().then((res) => {
        if(res.code == 1) {
          this.adminList = res.data;
          // console.log(this.adminList);
        }
      })
    }
  },
};
</script>

<style>
</style>


